      - { label: "Name", bind: "$.NAME" }
      - { label: "Length", bind: "$.LENGTH" }
      - { label: "Family", bind: "$.FAMILY" }
      - { label: "Sequence", bind: "$.SEQUENCE" }
      - { label: "Active site", bind: "$.ACTIVE_SITE" }
